import json
import sys


def decide(event):
    # Reinforce exact-phrase extraction right after the Skill tool loads,
    # while leaving every other hook event unchanged. Treat malformed hook
    # payloads as a no-op so the native execution path can continue.
    if not isinstance(event, dict):
        return {}
    if event.get("hook_event_name") == "PostToolUse" and event.get("tool_name") == "Skill":
        return {
            "hookSpecificOutput": {
                "hookEventName": "PostToolUse",
                "additionalContext": (
                    "Return only the short answer from the supplied context. "
                    "Copy the answer phrase exactly as written, preserving its full "
                    "surface form: do not paraphrase, normalize, convert word forms, "
                    "or drop trailing comma-separated location qualifiers such as "
                    "city, state, or country. For location/base questions return the "
                    "complete place phrase from the context; for sport/type/description "
                    "questions return the exact noun phrase used in the context. "
                    "Do not add explanation or extra tokens."
                ),
            }
        }
    return {}


if __name__ == "__main__":
    event = json.load(sys.stdin)
    print(json.dumps(decide(event)))

