    "move", "need", "offer", "open", "pass", "permit", "plan", "prevent",
    "produce", "promise", "protect", "provide", "put", "reach", "receive",
    "reduce", "remain", "require", "return", "rise", "run", "secure", "see",
    "seek", "seem", "send", "serve", "set", "show", "speak", "spread", "start",
